<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import http from'../../api/http';import TablePager from'../../shared/components/TablePager.vue';const props=defineProps<{kind:string}>();const cs:any={sales:{title:'销售订单',api:'/erp/sales-orders'},credits:{title:'信用管理',api:'/erp/credits'},mrp:{title:'物料需求计划',api:'/erp/mrp/runs'},suggestions:{title:'计划建议',api:'/erp/mrp/suggestions'},production:{title:'生产订单',api:'/erp/production-orders/p2'},receivables:{title:'应收账款',api:'/erp/receivables'},invoices:{title:'销售发票',api:'/erp/invoices'},receipts:{title:'回款与核销',api:'/erp/receipts'},payables:{title:'应付账款',api:'/erp/payables'},vouchers:{title:'业务凭证',api:'/erp/financial-vouchers'}};const c=computed(()=>cs[props.kind]),rows=ref<any[]>([]),page=ref(1),size=ref(20),total=ref(0),keyword=ref(''),status=ref(''),loading=ref(false),dialog=ref(false),form=reactive<any>({});async function load(){loading.value=true;try{const{data}=await http.get(c.value.api,{params:{page:page.value,size:size.value,keyword:keyword.value||undefined,status:status.value||undefined}});rows.value=data.data.content;total.value=data.data.totalElements}finally{loading.value=false}}function create(){Object.keys(form).forEach(k=>delete form[k]);if(props.kind==='mrp')Object.assign(form,{runType:'ORDER',factoryCode:'F001',planDate:new Date().toISOString().slice(0,10)});if(props.kind==='sales')Object.assign(form,{salesOrderNo:`SO-M-${Date.now()}`,deliveryDate:new Date().toISOString().slice(0,10),lines:[{lineNo:1,materialCode:'',orderQty:1,unitPrice:0,unitCode:'PCS'}]});dialog.value=true}async function save(){await http.post(c.value.api,form);ElMessage.success('保存成功');dialog.value=false;await load()}async function action(row:any,path:string,label:string,body:any={}){try{const{data}=await http.post(`/erp/${path.replace('{id}',row.id)}`,body);ElMessage.success(`${label}成功`);if(data.data)ElMessageBox.alert(JSON.stringify(data.data,null,2),`${label}结果`);await load()}catch(e:any){ElMessage.error(e.message||`${label}失败`)}}async function prompt(row:any,path:string,label:string,key='reason'){try{const{value}=await ElMessageBox.prompt(`请输入${label}信息`,label);await action(row,path,label,{[key]:value})}catch{}}async function settle(row:any){try{const a=await ElMessageBox.prompt('请输入应收记录编号','回款核销');const b=await ElMessageBox.prompt('请输入本次核销金额','回款核销');await http.post('/erp/settlements',{receiptId:row.id,receivableId:Number(a.value),amount:Number(b.value)});ElMessage.success('核销成功');await load()}catch(e:any){if(e!=='cancel')ElMessage.error(e.message||'核销失败')}}watch(()=>props.kind,()=>{page.value=1;load()});onMounted(load)</script>
<template><section class="page"><div class="head"><div><span>企业资源计划业务</span><h1>{{c.title}}</h1><p>订单、信用、交期、计划与财务台账的真实状态流转。</p></div><el-button v-if="['sales','mrp','invoices','receipts','payables'].includes(kind)" type="primary" @click="create">新增{{c.title}}</el-button></div><el-card shadow="never"><div class="bar"><el-input v-model="keyword" clearable placeholder="输入单号、客户或物料"/><el-select v-model="status" clearable placeholder="全部状态"><el-option v-for="s in ['DRAFT','CONFIRMED','CREATED','RUNNING','COMPLETED','PROPOSED','OPEN','PARTIAL','SETTLED']" :key="s" :label="$zh(s)" :value="s"/></el-select><el-button @click="page=1;load()">查询</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column v-for="k in Object.keys(rows[0]||{}).slice(0,9)" :key="k" :label="$zhKey(k)" min-width="125" show-overflow-tooltip><template #default="{row}">{{$zh(row[k])}}</template></el-table-column><el-table-column label="操作" width="310" fixed="right"><template #default="{row}"><template v-if="kind==='sales'"><el-button link @click="action(row,`sales-orders/${row.id}/credit-check`,'信用检查')">信用检查</el-button><el-button link @click="action(row,`sales-orders/${row.id}/atp`,'交期计算')">交期计算</el-button><el-button link @click="prompt(row,`sales-orders/${row.id}/atp/accept`,'确认交期')">确认交期</el-button><el-button link type="warning" @click="prompt(row,`sales-orders/${row.id}/credit-exception`,'信用例外审批')">信用例外</el-button><el-button link type="primary" @click="action(row,`sales-orders/${row.id}/confirm`,'确认订单')">确认</el-button><el-button link type="danger" @click="prompt(row,`sales-orders/${row.id}/cancel`,'取消')">取消</el-button></template><template v-if="kind==='mrp'"><el-button link type="primary" @click="action(row,`mrp/runs/${row.id}/execute`,'运行计划')">运行</el-button></template><template v-if="kind==='suggestions'"><el-button link type="primary" @click="action(row,`mrp/suggestions/${row.id}/confirm`,'确认建议')">确认建议</el-button></template><template v-if="kind==='receipts'"><el-button link type="primary" @click="settle(row)">核销应收</el-button></template><template v-if="kind==='production'"><el-button link @click="action(row,`production-orders/${row.id}/kit-check`,'齐套检查')">齐套检查</el-button><el-button link type="primary" @click="action(row,`production-orders/${row.id}/release`,'下达')">下达</el-button></template></template></el-table-column></el-table><TablePager v-model:page="page" v-model:size="size" :total="total" @change="load"/></el-card><el-dialog v-model="dialog" :title="`新增${c.title}`" width="620px"><el-form label-position="top"><template v-if="kind==='sales'"><el-form-item label="订单编号"><el-input v-model="form.salesOrderNo"/></el-form-item><el-form-item label="客户编码"><el-input v-model="form.customerCode"/></el-form-item><el-form-item label="要求交期"><el-date-picker v-model="form.deliveryDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="物料编码"><el-input v-model="form.lines[0].materialCode"/></el-form-item><el-form-item label="数量"><el-input-number v-model="form.lines[0].orderQty"/></el-form-item><el-form-item label="单价"><el-input-number v-model="form.lines[0].unitPrice"/></el-form-item></template><template v-if="kind==='mrp'"><el-form-item label="销售订单号"><el-input v-model="form.salesOrderNo"/></el-form-item><el-form-item label="工厂"><el-input v-model="form.factoryCode"/></el-form-item><el-form-item label="计划日期"><el-date-picker v-model="form.planDate" value-format="YYYY-MM-DD"/></el-form-item></template><template v-if="kind==='invoices'"><el-form-item label="发票号"><el-input v-model="form.invoiceNo"/></el-form-item><el-form-item label="销售订单号"><el-input v-model="form.salesOrderNo"/></el-form-item><el-form-item label="开票金额"><el-input-number v-model="form.amount"/></el-form-item><el-form-item label="税额"><el-input-number v-model="form.taxAmount"/></el-form-item></template><template v-if="kind==='payables'"><el-form-item label="应付单号"><el-input v-model="form.payableNo"/></el-form-item><el-form-item label="供应商编码"><el-input v-model="form.supplierCode"/></el-form-item><el-form-item label="采购来源单号"><el-input v-model="form.sourceOrderNo"/></el-form-item><el-form-item label="应付金额"><el-input-number v-model="form.amount"/></el-form-item><el-form-item label="到期日期"><el-date-picker v-model="form.dueDate" value-format="YYYY-MM-DD"/></el-form-item></template><template v-if="kind==='receipts'"><el-form-item label="回款单号"><el-input v-model="form.receiptNo"/></el-form-item><el-form-item label="客户编码"><el-input v-model="form.customerCode"/></el-form-item><el-form-item label="银行流水"><el-input v-model="form.bankReference"/></el-form-item><el-form-item label="回款日期"><el-date-picker v-model="form.receiptDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="金额"><el-input-number v-model="form.amount"/></el-form-item></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.page{max-width:1500px;margin:auto}.head{display:flex;align-items:end;justify-content:space-between;margin-bottom:16px}.head span{font-size:11px;color:#3976d5}.head h1{margin:5px 0;color:#263f5c}.head p{font-size:12px;color:#8391a4}.bar{display:flex;gap:8px;margin-bottom:14px}.bar .el-input{width:280px}.bar .el-select{width:160px}</style>
